import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 17

    try:
        records = list(
            csv.reader(
                io.StringIO(raw_csv, newline=""),
                delimiter=";",
                quotechar='"',
                doublequote=True,
                strict=False,
            )
        )
    except csv.Error:
        records = []
        for line in raw_csv.splitlines():
            try:
                records.extend(
                    csv.reader(
                        [line],
                        delimiter=";",
                        quotechar='"',
                        doublequote=True,
                        strict=False,
                    )
                )
            except csv.Error:
                records.append(line.split(";"))

    nonempty = [
        (index, row)
        for index, row in enumerate(records[:100])
        if row and any(value.strip() for value in row)
    ]
    if not nonempty:
        return {"columns": [f"column_{i + 1}" for i in range(expected_width)], "rows": []}

    def header_score(item):
        index, row = item
        score = -2 * abs(len(row) - expected_width) - index * 0.01
        for value in row:
            has_alpha = any(char.isalpha() for char in value)
            has_digit = any(char.isdigit() for char in value)
            if has_alpha and not has_digit:
                score += 3
            elif has_alpha:
                score += 1
        return score

    header_index, header = max(nonempty, key=header_score)
    rows = records[header_index + 1 :]

    width = max(
        expected_width,
        len(header),
        max((len(row) for row in rows), default=0),
    )
    columns = list(header)
    columns.extend(f"column_{i + 1}" for i in range(len(columns), width))

    normalized_rows = []
    for row in rows:
        normalized_rows.append(list(row) + [""] * (width - len(row)))

    return {"columns": columns, "rows": normalized_rows}
